fn fibonacci(n: usize) -> Vec<i32> {
    let mut ret: Vec<i32> = Vec::with_capacity(n);
    
    // Initialize first two Fibonacci numbers
    ret.push(0);  // F(0) = 0
    ret.push(1);  // F(1) = 1
    
    // Compute remaining Fibonacci numbers
    let mut i: usize = 2;
    while i < n {
        let fib = ret[i - 1] + ret[i - 2];
        ret.push(fib);
        i += 1;
    }
    
    ret
}